<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Configuración | CampoSur</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><section class="module-content"><header class="admin-header"><div><p class="eyebrow">Datos de la empresa</p><h1>Configuración de la empresa</h1><p class="setup-copy">Actualiza aquí los datos que verás en el sistema y en tus informes.</p></div><a class="secondary-link" href="./">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><article class="admin-panel settings-panel"><form method="post" enctype="multipart/form-data" class="admin-form settings-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><fieldset><legend>Identidad</legend><label>Razón social<input name="legal_name" required value="<?= htmlspecialchars($company['legal_name'] ?? '') ?>"></label><label>Nombre visible<input name="trade_name" required value="<?= htmlspecialchars($company['trade_name'] ?? '') ?>"></label><label>RUT<input name="tax_id" value="<?= htmlspecialchars($company['tax_id'] ?? '') ?>"></label><label>Logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG o WEBP · máximo 2 MB</small></label></fieldset><fieldset><legend>Contacto y ubicación</legend><label>Correo<input type="email" name="email" value="<?= htmlspecialchars($company['email'] ?? '') ?>"></label><label>Teléfono<input name="phone" value="<?= htmlspecialchars($company['phone'] ?? '') ?>"></label><label>Dirección<input name="address" value="<?= htmlspecialchars($company['address'] ?? '') ?>"></label><label>Comuna<input name="commune" value="<?= htmlspecialchars($company['commune'] ?? '') ?>"></label><label>Región<input name="region" value="<?= htmlspecialchars($company['region'] ?? '') ?>"></label></fieldset><button class="primary-button" type="submit">Guardar configuración</button></form></article></section></main></body></html>
